/// Stable identifier for one central square class of one Cartan's fiber.
///
/// The number IS the coset coordinate integer of the class in the crate's
/// echelon basis of (adjoint fiber group) / im(toAdjoint). The stage-(d)
/// ordering audit (`SEED_X0_DESIGN.md`) proved the crate's basis election
/// coincides with upstream's, so these numbers EQUAL upstream's square-class
/// numbers today; the coincidence rides on the shared low-pivot RREF
/// convention, and a basis change on either side would permute LABELS only
/// (partition structure and all sizes are convention-invariant).
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct SquareClassId(pub(crate) usize);

impl SquareClassId {
    /// The coset-coordinate integer of the class — the `class #N` number of
    /// upstream's `printStrongReal` (output.cpp:524).
    pub fn index(&self) -> usize {
        self.0
    }
}

/// A strong real form representative: a `W_im` orbit in the fiber group of
/// one square class, lying over one weak real form.
///
/// The `fiber_orbit` NUMBER depends on the particular solution this crate's
/// elimination picks — upstream's convention differs — but the orbit's
/// class size does not: translation by `ker(toAdjoint)` commutes with the
/// action.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct StrongRealFormRep {
    fiber_orbit: usize,
    square_class: SquareClassId,
}

impl StrongRealFormRep {
    pub fn fiber_orbit(&self) -> usize {
        self.fiber_orbit
    }

    pub fn square_class(&self) -> SquareClassId {
        self.square_class
    }
}

/// The strong-real layer of one Cartan class: square classes, per-square
/// fiber-orbit sizes, and strong representatives.
#[derive(Clone, Debug)]
pub struct StrongRealData {
    central_square_classes: Vec<SquareClassId>,
    class_bases: Vec<AdjointFiberElement>,
    orbit_sizes: Vec<Vec<usize>>,
    orbit_elements: Vec<Vec<Vec<u64>>>,
    to_weak_real: Vec<Vec<usize>>,
    strong_representatives: Vec<StrongRealFormRep>,
    wrf_preimage_masks: Vec<u64>,
}

impl StrongRealData {
    pub fn square_class_count(&self) -> usize {
        self.class_bases.len()
    }

    /// The square-class ids in ascending order, for external consumers that
    /// cannot construct [`SquareClassId`] values directly.
    pub fn square_classes(&self) -> impl ExactSizeIterator<Item = SquareClassId> + '_ {
        (0..self.class_bases.len()).map(SquareClassId)
    }

    /// Bounded by the Cartan's local weak class count.
    pub fn central_square_class(&self, local: WeakRealFormId) -> Option<SquareClassId> {
        self.central_square_classes.get(local.0).copied()
    }

    /// Bounded by the Cartan's local weak class count.
    pub fn strong_real_form(&self, local: WeakRealFormId) -> Option<StrongRealFormRep> {
        self.strong_representatives.get(local.0).copied()
    }

    /// The number of `W_im` orbits in one square class's fiber partition.
    pub fn fiber_orbit_count(&self, square: SquareClassId) -> Option<usize> {
        self.orbit_sizes.get(square.0).map(Vec::len)
    }

    /// The lowest-numbered local weak class of one square class — upstream
    /// `realFormPartition().classRep(csc)` (makeRealFormPartition elects
    /// the first form it meets, and forms are swept ascending).
    pub fn square_class_representative(&self, square: SquareClassId) -> Option<WeakRealFormId> {
        let position = self
            .central_square_classes
            .iter()
            .position(|candidate| *candidate == square)?;
        Some(WeakRealFormId(position))
    }

    /// The fiber-element masks of one orbit, ascending (the
    /// `printStrongReal` `[...]` list; its length is the parenthesised
    /// count). Bounded by the square class count and the orbit count.
    pub fn orbit_elements(&self, square: SquareClassId, orbit: usize) -> Option<&[u64]> {
        self.orbit_elements
            .get(square.0)?
            .get(orbit)
            .map(Vec::as_slice)
    }

    /// The weak real form lying under one strong orbit: upstream
    /// `Fiber::toWeakReal` (cartanclass.cpp:812-817), the adjoint orbit of
    /// `class_base(csc) + toAdjoint(rep)` with `rep` the orbit's
    /// representative fiber element. Bounded by the square class count and
    /// that class's orbit count.
    pub fn weak_real_of_orbit(
        &self,
        square: SquareClassId,
        orbit: usize,
    ) -> Option<WeakRealFormId> {
        self.to_weak_real
            .get(square.0)?
            .get(orbit)
            .copied()
            .map(WeakRealFormId)
    }

    /// The fiber element solving `toAdjoint(y) = wrf_rep - class_base` for
    /// one local weak class — upstream's `y = toAdjoint().section() * diff`
    /// of `InnerClass::central_fiber` (innerclass.cpp:1050-1052), as a mask
    /// over the ambient fiber basis. Bounded by the local weak class count.
    pub fn wrf_preimage_mask(&self, local: WeakRealFormId) -> Option<u64> {
        self.wrf_preimage_masks.get(local.0).copied()
    }

    /// The fiber size of one local weak class: the class size of its strong
    /// representative's orbit.
    pub fn fiber_size(&self, local: WeakRealFormId) -> Option<usize> {
        let representative = self.strong_real_form(local)?;
        self.orbit_sizes
            .get(representative.square_class.0)?
            .get(representative.fiber_orbit)
            .copied()
    }
}

/// The strong-real layer of a whole inner class, with the KGB sizes — the
/// first differential numbers comparable against published Atlas values.
#[derive(Clone, Debug)]
pub struct StrongRealClassification {
    per_cartan: Vec<StrongRealData>,
    local_of_form: Vec<Vec<Option<usize>>>,
    kgb_sizes: Vec<usize>,
    global_kgb_size: usize,
}

impl StrongRealClassification {
    /// Build the strong-real layer over a finished Cartan classification.
    pub fn build(
        classification: &CartanClassification,
        max_fiber_elements: usize,
    ) -> Result<Self, StructureError> {
        let mut per_cartan = try_capacity(classification.cartan_classes().len())?;
        let mut global_kgb_size = 0_usize;
        for cartan_class in classification.cartan_classes() {
            let grading = cartan_class.grading();
            let adjoint = grading.adjoint_fiber();
            let ambient = adjoint.ambient_fiber();
            // The accessor constructs the map, so obtain it once per Cartan.
            let fiber_map = adjoint.fiber_map();
            let weak = cartan_class.partition();
            let fiber_dimension = ambient.dimension();
            let adjoint_dimension = adjoint.dimension();
            if fiber_dimension > MAX_MASK_BITS {
                return Err(StructureError::StrongRealResourceLimit {
                    resource: "mask bits",
                    limit: MAX_MASK_BITS,
                });
            }

            // Ambient basis images and their adjoint coordinates.
            let mut image_elements = try_capacity(fiber_dimension)?;
            let mut image_coordinates: Vec<ModTwoVector> = try_capacity(fiber_dimension)?;
            for representative in ambient.basis_representatives() {
                let element = ambient.element_from_ambient(representative.clone())?;
                let image = fiber_map.apply(&element)?;
                image_coordinates.push(adjoint.coordinates(&image)?.clone());
                image_elements.push(image);
            }

            // The square quotient: full-space numerator over im(toAdjoint).
            let mut numerator = ModTwoSubspace::new(adjoint_dimension)?;
            for index in 0..adjoint_dimension {
                numerator.insert(ModTwoVector::from_ones(adjoint_dimension, [index])?)?;
            }
            let mut denominator = ModTwoSubspace::new(adjoint_dimension)?;
            for coordinates in &image_coordinates {
                denominator.insert(coordinates.clone())?;
            }
            let quotient = ModTwoSubquotient::new(numerator, denominator)?;
            let quotient_dimension = quotient.dimension();
            let square_class_count = 1_usize
                .checked_shl(
                    u32::try_from(quotient_dimension)
                        .map_err(|_| StructureError::ArithmeticOverflow)?,
                )
                .ok_or(StructureError::ArithmeticOverflow)?;

            // Central square class per local weak class, with surjectivity.
            let local_count = weak.class_count();
            let mut central_square_classes = try_capacity(local_count)?;
            for local in weak.classes() {
                let representative =
                    weak.class_representative(local)
                        .ok_or(StructureError::IndexOutOfRange {
                            index: local.0,
                            upper_bound: local_count,
                        })?;
                let coordinates = adjoint.coordinates(representative)?.clone();
                let quotient_coordinates = quotient.to_coordinates(coordinates)?;
                let mut value = 0_usize;
                for bit in 0..quotient_dimension {
                    if quotient_coordinates.bit(bit) == Some(true) {
                        value |= 1_usize << bit;
                    }
                }
                central_square_classes.push(SquareClassId(value));
            }
            let mut base_local = try_capacity(square_class_count)?;
            base_local.resize(square_class_count, None::<usize>);
            for (local_index, square) in central_square_classes.iter().enumerate() {
                if base_local[square.0].is_none() {
                    base_local[square.0] = Some(local_index);
                }
            }
            let mut class_bases = try_capacity(square_class_count)?;
            for slot in &base_local {
                let local_index = slot.ok_or(StructureError::StrongRealInvariantViolation {
                    invariant: "square class count",
                })?;
                class_bases.push(
                    weak.class_representative(WeakRealFormId(local_index))
                        .ok_or(StructureError::IndexOutOfRange {
                            index: local_index,
                            upper_bound: local_count,
                        })?
                        .clone(),
                );
            }

            // The square-class-independent fiber-side shift columns and the
            // ambient translation masks. Columns are measured against the
            // ambient all-noncompact base grading (the grading of the zero
            // adjoint element), never a per-class base.
            let imaginary_rank = grading.imaginary_rank();
            let base_grading = grading.base_grading();
            let mut alpha_columns = try_capacity(imaginary_rank)?;
            alpha_columns.resize(imaginary_rank, 0_u64);
            for (basis_index, image) in image_elements.iter().enumerate() {
                let image_grading = grading.grading(image)?;
                for (imaginary_index, column) in alpha_columns.iter_mut().enumerate() {
                    if image_grading.is_noncompact(imaginary_index)
                        != base_grading.is_noncompact(imaginary_index)
                    {
                        *column |= 1_u64 << basis_index;
                    }
                }
            }
            let mut m_alpha_masks = try_capacity(imaginary_rank)?;
            for imaginary_index in 0..imaginary_rank {
                let element =
                    grading
                        .m_alpha(imaginary_index)
                        .ok_or(StructureError::IndexOutOfRange {
                            index: imaginary_index,
                            upper_bound: imaginary_rank,
                        })?;
                let coordinates = ambient.coordinates(element)?;
                let mut mask = 0_u64;
                for bit in 0..fiber_dimension {
                    if coordinates.bit(bit) == Some(true) {
                        mask |= 1_u64 << bit;
                    }
                }
                m_alpha_masks.push(mask);
            }

            // One walk per square class; tables stay transient but live long
            // enough to classify the strong-representative solutions.
            let mut orbit_sizes = try_capacity(square_class_count)?;
            let mut orbit_elements = try_capacity(square_class_count)?;
            let mut to_weak_real = try_capacity(square_class_count)?;
            let mut tables = try_capacity(square_class_count)?;
            for base_element in &class_bases {
                let class_grading = grading.grading(base_element)?;
                let mut base_bits = try_capacity(imaginary_rank)?;
                for imaginary_index in 0..imaginary_rank {
                    base_bits.push(class_grading.is_noncompact(imaginary_index).ok_or(
                        StructureError::IndexOutOfRange {
                            index: imaginary_index,
                            upper_bound: imaginary_rank,
                        },
                    )?);
                }
                let orbits = walk_mask_orbits(
                    fiber_dimension,
                    max_fiber_elements,
                    &base_bits,
                    &alpha_columns,
                    &m_alpha_masks,
                    strong_limit_error,
                )?;
                let mut sizes = try_capacity(orbits.representative_masks.len())?;
                sizes.resize(orbits.representative_masks.len(), 0_usize);
                for &class in &orbits.class_of_by_mask {
                    let class =
                        usize::try_from(class).map_err(|_| StructureError::ArithmeticOverflow)?;
                    sizes[class] = sizes[class]
                        .checked_add(1)
                        .ok_or(StructureError::ArithmeticOverflow)?;
                }
                // Per-orbit member masks, ascending — the order upstream's
                // PartitionIterator serves a class's elements in (its
                // stable sort by class, partition.cpp:148-177), which the
                // `printStrongReal` orbit lists echo verbatim.
                let mut members = try_capacity(orbits.representative_masks.len())?;
                members.resize_with(orbits.representative_masks.len(), Vec::new);
                for (index, &class) in orbits.class_of_by_mask.iter().enumerate() {
                    let class =
                        usize::try_from(class).map_err(|_| StructureError::ArithmeticOverflow)?;
                    members[class].push(
                        u64::try_from(index).map_err(|_| StructureError::ArithmeticOverflow)?,
                    );
                }
                // toWeakReal per orbit: the adjoint orbit of
                // `class_base(csc) + toAdjoint(rep)`, with `rep` the fiber
                // element of the orbit's representative mask. The mask bits
                // index the AMBIENT (source) fiber basis, so `rep` expands
                // in the full coweight lattice — including any central-torus
                // directions — not in the adjoint datum's smaller lattice
                // (upstream `FiberElt rep(..., fiberRank())`,
                // cartanclass.cpp:812).
                let ambient_rank = ambient.lattice_rank();
                let mut weak_row = try_capacity(orbits.representative_masks.len())?;
                for &mask in &orbits.representative_masks {
                    let mut representative = ModTwoVector::zero(ambient_rank)?;
                    for (index, basis) in ambient.basis_representatives().iter().enumerate() {
                        if mask & (1_u64 << index) != 0 {
                            representative.xor_assign(basis)?;
                        }
                    }
                    let element = ambient.element_from_ambient(representative)?;
                    let image = fiber_map.apply(&element)?;
                    let sum = adjoint.add(&image, base_element)?;
                    weak_row.push(weak.class_of(&sum)?.0);
                }
                orbit_sizes.push(sizes);
                orbit_elements.push(members);
                to_weak_real.push(weak_row);
                tables.push(orbits.class_of_by_mask);
            }

            // Strong representatives: solve toAdjoint(x) = rep XOR base per
            // local class, then classify the solution mask.
            let section = crate::mod_two::CanonicalModTwoSection::new(
                adjoint_dimension,
                &image_coordinates,
            )?;
            let mut strong_representatives = try_capacity(local_count)?;
            let mut wrf_preimage_masks = try_capacity(local_count)?;
            for (local_index, square) in central_square_classes.iter().enumerate() {
                let representative = weak
                    .class_representative(WeakRealFormId(local_index))
                    .ok_or(StructureError::IndexOutOfRange {
                        index: local_index,
                        upper_bound: local_count,
                    })?;
                let difference = adjoint.add(representative, &class_bases[square.0])?;
                let coordinates = adjoint.coordinates(&difference)?;
                let mask = section.solve(&coordinates)?.ok_or(
                    StructureError::StrongRealInvariantViolation {
                        invariant: "strong representative",
                    },
                )?;
                let mask_index =
                    usize::try_from(mask).map_err(|_| StructureError::ArithmeticOverflow)?;
                let fiber_orbit = usize::try_from(tables[square.0][mask_index])
                    .map_err(|_| StructureError::ArithmeticOverflow)?;
                strong_representatives.push(StrongRealFormRep {
                    fiber_orbit,
                    square_class: *square,
                });
                wrf_preimage_masks.push(mask);
            }

            // Global term: orbitSize * squareClassCount * 2^fiberRank.
            let fiber_size_total = 1_usize
                .checked_shl(
                    u32::try_from(fiber_dimension)
                        .map_err(|_| StructureError::ArithmeticOverflow)?,
                )
                .ok_or(StructureError::ArithmeticOverflow)?;
            let term = cartan_class
                .twisted_involution_count()
                .checked_mul(square_class_count)
                .and_then(|value| value.checked_mul(fiber_size_total))
                .ok_or(StructureError::ArithmeticOverflow)?;
            global_kgb_size = global_kgb_size
                .checked_add(term)
                .ok_or(StructureError::ArithmeticOverflow)?;

            per_cartan.push(StrongRealData {
                central_square_classes,
                class_bases,
                orbit_sizes,
                orbit_elements,
                to_weak_real,
                strong_representatives,
                wrf_preimage_masks,
            });
        }

        // The global-form-to-local-class table, then the precomputed sizes.
        let form_count = classification.weak_real_form_count();
        let mut local_of_form = try_capacity(classification.cartan_classes().len())?;
        for cartan_class in classification.cartan_classes() {
            let mut row = try_capacity(form_count)?;
            for form_index in 0..form_count {
                row.push(
                    cartan_class
                        .labels()
                        .labels()
                        .iter()
                        .position(|&label| label == WeakRealFormId(form_index)),
                );
            }
            local_of_form.push(row);
        }
        let mut kgb_sizes = try_capacity(form_count)?;
        // form_index also names the form and its error payloads; iterating
        // local_of_form would invert its cartan-major layout.
        #[allow(clippy::needless_range_loop)]
        for form_index in 0..form_count {
            let form = WeakRealFormId(form_index);
            let cartan_set =
                classification
                    .cartan_set(form)
                    .ok_or(StructureError::IndexOutOfRange {
                        index: form_index,
                        upper_bound: form_count,
                    })?;
            let mut total = 0_usize;
            for &cartan in cartan_set {
                let cartan_class =
                    classification
                        .cartan_class(cartan)
                        .ok_or(StructureError::IndexOutOfRange {
                            index: cartan.0,
                            upper_bound: classification.cartan_classes().len(),
                        })?;
                let local_index = local_of_form[cartan.0][form_index].ok_or(
                    StructureError::StrongRealInvariantViolation {
                        invariant: "square class consistency",
                    },
                )?;
                let fiber_size = per_cartan[cartan.0]
                    .fiber_size(WeakRealFormId(local_index))
                    .ok_or(StructureError::StrongRealInvariantViolation {
                        invariant: "square class consistency",
                    })?;
                let term = cartan_class
                    .twisted_involution_count()
                    .checked_mul(fiber_size)
                    .ok_or(StructureError::ArithmeticOverflow)?;
                total = total
                    .checked_add(term)
                    .ok_or(StructureError::ArithmeticOverflow)?;
            }
            kgb_sizes.push(total);
        }

        Ok(Self {
            per_cartan,
            local_of_form,
            kgb_sizes,
            global_kgb_size,
        })
    }

    /// Bounded by the Cartan class count.
    pub fn strong_real_data(&self, cartan: CartanId) -> Option<&StrongRealData> {
        self.per_cartan.get(cartan.0)
    }

    /// The fiber size of a GLOBAL form at one Cartan. `None` only for an
    /// out-of-range id; a valid pair where the form does not live at that
    /// Cartan is `Some(0)`, so sums over all Cartans stay correct.
    pub fn fiber_size(&self, form: WeakRealFormId, cartan: CartanId) -> Option<usize> {
        let data = self.per_cartan.get(cartan.0)?;
        match *self.local_of_form.get(cartan.0)?.get(form.0)? {
            Some(local) => data.fiber_size(WeakRealFormId(local)),
            None => Some(0),
        }
    }

    /// The precomputed KGB size of one real form. Bounded by the form count.
    pub fn kgb_size(&self, form: WeakRealFormId) -> Option<usize> {
        self.kgb_sizes.get(form.0).copied()
    }

    /// The total over all strong real forms.
    pub fn global_kgb_size(&self) -> usize {
        self.global_kgb_size
    }
}

/// One square class's `printStrongReal` block (upstream output.cpp:503-537):
/// the fundamental square-class number, the elected possible-square
/// coweight, and the per-orbit external form numbers with their fiber
/// elements.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct StrongRealClassPrint {
    class_number: usize,
    square_numerators: Vec<i64>,
    square_denominator: u64,
    real_forms: Vec<(usize, Vec<u64>)>,
}

impl StrongRealClassPrint {
    /// The `class #N` number: `xi_square` of the class representative,
    /// lifted to the fundamental fiber (output.cpp:506-508).
    pub fn class_number(&self) -> usize {
        self.class_number
    }

    /// The `z` of `possible square: exp(2i\pi(z))`: numerators over one
    /// positive denominator, each numerator already reduced to its
    /// nonnegative remainder modulo the denominator (output.cpp:519-521).
    pub fn square(&self) -> (&[i64], u64) {
        (&self.square_numerators, self.square_denominator)
    }

    /// Per orbit, in partition order: the weak form's EXTERNAL number
    /// (upstream `rfi.out`, which may repeat across orbits) and its
    /// ascending fiber-element masks (the `[...]` list; its length is the
    /// parenthesised count).
    pub fn real_forms(&self) -> &[(usize, Vec<u64>)] {
        &self.real_forms
    }
}

/// The `printStrongReal` data of one Cartan class, one block per square
/// class in ascending order (output.cpp:490-540).
pub fn strong_real_class_prints(
    inner_class: &InnerClass,
    classification: &CartanClassification,
    strong: &StrongRealClassification,
    order: &ExternalFormOrder,
    cartan: CartanId,
    budget: &IntegerLatticeBudget,
) -> Result<Vec<StrongRealClassPrint>, StructureError> {
    let cartan_class =
        classification
            .cartan_class(cartan)
            .ok_or(StructureError::IndexOutOfRange {
                index: cartan.0,
                upper_bound: classification.cartan_classes().len(),
            })?;
    let data = strong
        .strong_real_data(cartan)
        .ok_or(StructureError::IndexOutOfRange {
            index: cartan.0,
            upper_bound: classification.cartan_classes().len(),
        })?;
    let fundamental = classification.cartan_class(CartanId(0)).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "fundamental class",
        },
    )?;
    let fundamental_data = strong.strong_real_data(CartanId(0)).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "fundamental class",
        },
    )?;

    let datum = inner_class.datum();
    let system = inner_class.root_system();
    let delta_data = inner_class.distinguished_involution();
    let simple_ids = system.simple_root_ids();
    let lattice_rank = datum.lattice_rank();
    let coweights = fundamental_coweights(datum)?;
    // stable_log takes the xi^T-plus-one matrix (y_values.cpp:155-166).
    let mut xi_plus_one = try_capacity(lattice_rank)?;
    for (index, row) in delta_data.involution().coweight_matrix().iter().enumerate() {
        let mut entries = try_capacity(lattice_rank)?;
        for (column, &value) in row.iter().enumerate() {
            entries.push(if index == column { value + 1 } else { value });
        }
        xi_plus_one.push(entries);
    }

    let mut result = try_capacity(data.square_class_count())?;
    for square in data.square_classes() {
        // xi_square of the class representative, lifted through the labels
        // into the fundamental fiber (output.cpp:506-508).
        let local = data.square_class_representative(square).ok_or(
            StructureError::StrongRealInvariantViolation {
                invariant: "square class representative",
            },
        )?;
        let global = cartan_class.labels().label(local).ok_or(
            StructureError::StrongRealInvariantViolation {
                invariant: "square class representative",
            },
        )?;
        let fundamental_square = fundamental_data.central_square_class(global).ok_or(
            StructureError::StrongRealInvariantViolation {
                invariant: "square class representative",
            },
        )?;

        // some_coch (innerclass.cpp:966-977): the fundamental coweights of
        // the square-class representative's COMPACT delta-fixed simples,
        // summed, then stably logged.
        let fundamental_local = fundamental_data
            .square_class_representative(fundamental_square)
            .ok_or(StructureError::StrongRealInvariantViolation {
                invariant: "square class representative",
            })?;
        let base_element = fundamental
            .partition()
            .class_representative(fundamental_local)
            .ok_or(StructureError::StrongRealInvariantViolation {
                invariant: "square class representative",
            })?;
        let base_grading = fundamental.grading().grading(base_element)?;
        let mut coch_rep = try_capacity(lattice_rank)?;
        coch_rep.resize(lattice_rank, Rational::ZERO);
        for (generator, &simple_id) in simple_ids.iter().enumerate() {
            if delta_data.image(simple_id) != Some(simple_id) {
                continue;
            }
            let position = fundamental
                .grading()
                .imaginary_simple_roots()
                .iter()
                .position(|&candidate| candidate == simple_id)
                .ok_or(StructureError::StrongRealInvariantViolation {
                    invariant: "fixed simple root",
                })?;
            if !base_grading.is_noncompact(position).ok_or(
                StructureError::StrongRealInvariantViolation {
                    invariant: "fixed simple root",
                },
            )? {
                for (slot, value) in coch_rep.iter_mut().zip(&coweights[generator]) {
                    *slot += value;
                }
            }
        }
        let coch = stable_log(&coch_rep, &xi_plus_one, budget)?;

        // grading_of_simples (innerclass.cpp:1295-1304): a simple root is
        // marked when its pairing with the cocharacter is EVEN; `z` sums
        // the fundamental coweights of the marked simples.
        let mut z = try_capacity(lattice_rank)?;
        z.resize(lattice_rank, Rational::ZERO);
        for (generator, root) in datum.simple_roots().iter().enumerate() {
            let mut pairing = Rational::ZERO;
            for (value, &coordinate) in coch.iter().zip(root.as_slice()) {
                pairing += value.clone() * Rational::from(coordinate);
            }
            if fractional_part(&pairing) != Rational::ZERO {
                return Err(StructureError::StrongRealInvariantViolation {
                    invariant: "integral simple pairing",
                });
            }
            if pairing.floor().divisible_by(&Integer::from(2)) {
                for (slot, value) in z.iter_mut().zip(&coweights[generator]) {
                    *slot += value;
                }
            }
        }
        let (square_numerators, square_denominator) = normalized_remainder(&z)?;

        let orbit_count =
            data.fiber_orbit_count(square)
                .ok_or(StructureError::StrongRealInvariantViolation {
                    invariant: "square class count",
                })?;
        let mut real_forms = try_capacity(orbit_count)?;
        for orbit in 0..orbit_count {
            let local = data.weak_real_of_orbit(square, orbit).ok_or(
                StructureError::StrongRealInvariantViolation {
                    invariant: "orbit count",
                },
            )?;
            let global = cartan_class.labels().label(local).ok_or(
                StructureError::StrongRealInvariantViolation {
                    invariant: "orbit weak form",
                },
            )?;
            let external =
                order
                    .external(global)
                    .ok_or(StructureError::StrongRealInvariantViolation {
                        invariant: "orbit weak form",
                    })?;
            let elements = data.orbit_elements(square, orbit).ok_or(
                StructureError::StrongRealInvariantViolation {
                    invariant: "orbit count",
                },
            )?;
            real_forms.push((external, elements.to_vec()));
        }
        result.push(StrongRealClassPrint {
            class_number: fundamental_square.index(),
            square_numerators,
            square_denominator,
            real_forms,
        });
    }
    Ok(result)
}

/// `InnerClass::central_fiber` (innerclass.cpp:1042-1057): the fundamental
/// fiber's stabilizer of one real form's gradings, listed as ambient torus
/// parts (mod-two coweight vectors of the datum's lattice rank).
///
/// With `csc` the form's central square class in the fundamental fiber,
/// `diff = wrf_rep(form) - class_base(csc)`, and `y` the stored preimage
/// solve (`toAdjoint(y) == diff`), upstream's `preimage`
/// (innerclass.cpp:1020-1039) collects `fromBasis(fe + y)` for the members
/// `fe` of `y`'s strong orbit whose adjoint image is `diff`, swept in
/// ascending fiber-element order. The stored preimage uses upstream's
/// `BinaryMap::section` election: another valid preimage can permute the
/// emitted list, even when its set of elements agrees. Do not sort the
/// translated output; preserve both the elected preimage and member order.
pub fn central_fiber(
    classification: &CartanClassification,
    strong: &StrongRealClassification,
    form: WeakRealFormId,
) -> Result<Vec<ModTwoVector>, StructureError> {
    let fundamental = classification.cartan_class(CartanId(0)).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "fundamental class",
        },
    )?;
    let data = strong.strong_real_data(CartanId(0)).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "fundamental class",
        },
    )?;
    // Global form numbers are minted by the fundamental partition; go
    // through its labels anyway so a non-identity map would stay correct.
    let local = WeakRealFormId(
        fundamental
            .labels()
            .labels()
            .iter()
            .position(|&label| label == form)
            .ok_or(StructureError::StrongRealInvariantViolation {
                invariant: "fundamental real-form label",
            })?,
    );
    let square =
        data.central_square_class(local)
            .ok_or(StructureError::StrongRealInvariantViolation {
                invariant: "central square class",
            })?;
    let representative =
        data.strong_real_form(local)
            .ok_or(StructureError::StrongRealInvariantViolation {
                invariant: "strong representative",
            })?;
    let y = data
        .wrf_preimage_mask(local)
        .ok_or(StructureError::StrongRealInvariantViolation {
            invariant: "strong representative",
        })?;

    let partition = fundamental.partition();
    let adjoint = partition.adjoint_fiber();
    let ambient = adjoint.ambient_fiber();
    let fiber_map = adjoint.fiber_map();
    let target = partition.class_representative(local).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "weak class representative",
        },
    )?;
    let base_local = data.square_class_representative(square).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "square class representative",
        },
    )?;
    let base = partition.class_representative(base_local).ok_or(
        StructureError::StrongRealInvariantViolation {
            invariant: "square class representative",
        },
    )?;
    let difference = adjoint.add(target, base)?;
    let diff = adjoint.coordinates(&difference)?.clone();

    let members = data
        .orbit_elements(square, representative.fiber_orbit())
        .ok_or(StructureError::StrongRealInvariantViolation {
            invariant: "orbit count",
        })?;
    let mut result = try_capacity(members.len())?;
    for &member in members {
        let element = ambient.element_from_ambient(ambient_expansion(ambient, member)?)?;
        let image = fiber_map.apply(&element)?;
        if adjoint.coordinates(&image)? == &diff {
            result.push(ambient_expansion(ambient, member ^ y)?);
        }
    }
    Ok(result)
}

/// The ambient `Y/2Y` representative of a fiber-basis mask: the XOR of the
/// basis representatives the mask selects, which is exactly the owning
/// fiber's canonical representative of that element.
fn ambient_expansion(fiber: &CartanFiber, mask: u64) -> Result<ModTwoVector, StructureError> {
    let mut representative = ModTwoVector::zero(fiber.lattice_rank())?;
    for (index, basis) in fiber.basis_representatives().iter().enumerate() {
        if mask & (1_u64 << index) != 0 {
            representative.xor_assign(basis)?;
        }
    }
    Ok(representative)
}

/// `z` as one fraction — the shared denominator (lcm of the entry
/// denominators), gcd-normalised like upstream's `RatWeight`, then each
/// numerator reduced to its NONNEGATIVE remainder modulo the denominator
/// (upstream `arithmetic::remainder`, output.cpp:519-521). The remainder
/// pass preserves the gcd, so no second normalisation is needed.
fn normalized_remainder(z: &[Rational]) -> Result<(Vec<i64>, u64), StructureError> {
    let mut denominator = 1_u64;
    for value in z {
        let entry = u64::try_from(value.denominator_ref())
            .map_err(|_| StructureError::ArithmeticOverflow)?;
        denominator = denominator
            .checked_mul(entry / gcd_u64(denominator, entry))
            .ok_or(StructureError::ArithmeticOverflow)?;
    }
    let mut numerators = try_capacity(z.len())?;
    let mut divisor = denominator;
    for value in z {
        let scaled = value * Rational::from(denominator);
        let integer = Integer::try_from(&scaled).map_err(|_| {
            StructureError::StrongRealInvariantViolation {
                invariant: "square fraction",
            }
        })?;
        let numerator = i64::try_from(&integer).map_err(|_| StructureError::ArithmeticOverflow)?;
        divisor = gcd_u64(divisor, numerator.unsigned_abs());
        numerators.push(numerator);
    }
    if divisor > 1 {
        for numerator in &mut numerators {
            *numerator /= i64::try_from(divisor).map_err(|_| StructureError::ArithmeticOverflow)?;
        }
        denominator /= divisor;
    }
    let modulus = i64::try_from(denominator).map_err(|_| StructureError::ArithmeticOverflow)?;
    for numerator in &mut numerators {
        *numerator = numerator.rem_euclid(modulus);
    }
    Ok((numerators, denominator))
}

fn gcd_u64(mut left: u64, mut right: u64) -> u64 {
    while right != 0 {
        (left, right) = (right, left % right);
    }
    left
}

fn strong_limit_error(resource: &'static str, limit: usize) -> StructureError {
    StructureError::StrongRealResourceLimit { resource, limit }
}

